CREATE TABLE IF NOT EXISTS `benef` (
  `NUM_REG` int(11) NOT NULL COMMENT 'clave de indentificacion del beneficiario',
  `NOMBRE` varchar(254) DEFAULT NULL COMMENT 'nombre o descripcion del beneficiario',
  `RFC` varchar(15) DEFAULT NULL COMMENT 'registro federal de causantes que identifica al beneficiario',
  `CTA_CONTAB` varchar(40) DEFAULT NULL COMMENT 'Cuenta asociada de Aspel-COI a la cual se le aplicarán los montos',
  `TIPO` varchar(20) DEFAULT 'BENEFICIARIO' COMMENT 'Indica si será beneficiario, deudor o ambos.',
  `INF_GENERAL` varchar(250) DEFAULT NULL COMMENT 'Este campo puedes escribir la dirección, teléfono, e-mail, entre otros',
  `REFERENCIA` varchar(20) DEFAULT NULL COMMENT 'Indica la referencia para el beneficiario y/o Deudor, este puede ser un número, clave alfanumérica, entre otros.',
  `BANCO` varchar(30) DEFAULT NULL COMMENT 'clave del banco',
  `SUCURSAL` varchar(30) DEFAULT NULL COMMENT 'Indica el Número de sucursal de la cuenta',
  `CUENTA` varchar(30) DEFAULT NULL COMMENT 'Indica el Número de la cuenta a la que pertenece el beneficiario y/o deudor.',
  `CLABE` varchar(30) DEFAULT NULL COMMENT 'cuenta CLABE',
  `CVE_BANCO` varchar(30) DEFAULT NULL COMMENT 'Indica la clave del banco que manejará el tercero. Si marcas la opción "Es banco extranjero" automáticamente se asignará el código 999 y se inhabilitará el campo.',
  `ESBANCOEXT` int(11) DEFAULT 0 COMMENT 'Al marcar este campo se indica que el banco del tercero es extranjero y al generar la póliza se identificará con el código 999',
  `BANCODESC` varchar(20) DEFAULT NULL,
  `RFCBANCO` varchar(15) DEFAULT NULL COMMENT 'Indica el RFC del banco correspondiente al que pertenece la cuenta',
  PRIMARY KEY (`NUM_REG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='catalogo de beneficiarios, clientes, deudores y otros';

