CREATE TABLE IF NOT EXISTS `ctas` (
  `NUM_REG` int(11) NOT NULL COMMENT 'clave de la cuenta',
  `NUM_CTA` varchar(16) DEFAULT NULL COMMENT 'numero de la cuenta del banco',
  `STATUS` int(11) DEFAULT 1 COMMENT 'indica si la cuenta esta con estado 1=Activo o 0=Baja',
  `BANCO` varchar(20) DEFAULT NULL COMMENT 'nombre de la institucion bancaria a la que corresponde la cuenta',
  `SUCURSAL` varchar(6) DEFAULT NULL COMMENT 'Establecimiento del banco donde están registradas las cuentas (aparece en el estado de cuenta). Puede definirse con números o letras.',
  `MONEDA` int(11) DEFAULT 1 COMMENT 'Indica cual será la moneda con la que se operará la cuenta bancaria, los montos de los movimientos serán expresados en ésta.',
  `CTA_CONTAB` varchar(40) DEFAULT NULL COMMENT 'Si se maneja Interfaz COI en este campo deberá indicarse la cuenta contable que se afectará al contabilizar los movimientos de la cuenta .La cuenta no se debe dejar en blanco  ya que podría ocasionar problemas al momento de  capturar la póliza.',
  `DIA_CORTE` int(11) DEFAULT 30 COMMENT 'dia de corte de la cuenta bancaria',
  `SIG_CHEQUE` int(11) DEFAULT 1 COMMENT 'numero de cheque que le sigue',
  `FECH_APER` datetime NOT NULL COMMENT 'Fecha en la que se abrió la  cuenta bancaria, lo que permite llevar el registro de antigüedad de la cuenta.',
  `CHE_FTO` varchar(255) DEFAULT NULL COMMENT 'En este campo indicas el formato QR2 que se le aplicará a las operaciones con la cuenta que se está dando de alta. El archivo se encuentra en la ruta de trabajo.',
  `BMP_BAN` varchar(20) DEFAULT NULL COMMENT 'En este campo  podrás indicar la ruta donde tienes almacenado el logo del banco. Entre los formatos en los que puede estar creado tu logo, se encuentran: gif, bmp y jpg. Con la tecla F2 o con el botón  podrás buscar la ruta donde se encuentra el archivo del logo',
  `FUNCIONARIO` varchar(20) DEFAULT NULL COMMENT 'Es la persona de la institución bancaria que te atiende o lleva el control de tus cuentas',
  `TELEFONO` varchar(20) DEFAULT NULL COMMENT 'Registra el número telefónico de la sucursal del banco al que estás afiliado.',
  `CLABE` varchar(25) DEFAULT NULL COMMENT 'Número de la cuenta que se emplea para realizar operaciones con otros bancos',
  `PLAZA` varchar(20) DEFAULT NULL COMMENT 'Identifica la zona geográfica donde se ubica la sucursal donde se abrió la cuenta.',
  `CVE_BANCO` varchar(30) DEFAULT NULL COMMENT 'Clave asignada al banco por la Asociación de Banqueros de México.',
  `NOMBRE_CTA` varchar(20) DEFAULT NULL COMMENT 'Define el nombre para identificar a tus cuentas en las distintas consultas que contienen las pestañas horizontales, las cuales te ayudarán a cambiar de cuenta.',
  `SALDO_INI` double DEFAULT NULL COMMENT 'Monto inicial al crear la cuenta.',
  `ESBANCOEXT` int(11) DEFAULT 0 COMMENT 'Al marcar esta opción estás indicando que la cuenta es de un banco extranjero y automáticamente se le asignará el código 999 al campo clave del banco 999.',
  `RFC` varchar(15) DEFAULT '0' COMMENT ' Indica el RFC del Banco para poder generar captura de cuentas bancarias soportará recepciones de pagos',
  PRIMARY KEY (`NUM_REG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='catalogo de cuentas bancarias';

