  `X_OBSER` varchar(255) DEFAULT NULL,
  `FACTOR` int(11) NOT NULL,
  `FORMAPAGO` int(11) NOT NULL COMMENT 'Indica la forma de pago con la que se genera el movimiento. ',
  `ANOMBREDE` varchar(254) DEFAULT NULL COMMENT 'Dependiendo del concepto que se elija será el tipo de beneficiario que aparezca, si se eligió un abono, entonces el campo se llamará "Cliente, deudor, otro" de lo contrario se llamará "Beneficiario".',
  `ASOCIADO` varchar(1) NOT NULL,
  `CTA_CONTAB_ASOC` varchar(40) DEFAULT NULL,
  `REVISADO` int(11) DEFAULT 0,
  `PRIORIDAD` varchar(6) DEFAULT 'NORMAL' COMMENT 'Indica el tipo de trato que se le dará al movimiento ya sea prioridad  "Alta" o "Normal".',
