  `CUENTA` varchar(30) DEFAULT NULL,
  `CLABE` varchar(30) DEFAULT NULL,
  `MULTI_CLPV` int(11) DEFAULT NULL,
  `CVE_BANCO_ASOC` varchar(6) DEFAULT NULL,
  `NUM_CONC_AUTO` int(11) DEFAULT NULL,
  `COI_DEPTO` int(11) DEFAULT NULL,
  `COI_CCOSTOS` int(11) DEFAULT NULL,
  `COI_PROYECTO` int(11) DEFAULT NULL,
  `CUENTABAN_CLPV` varchar(30) DEFAULT NULL,
  `NOMBANCO` varchar(230) DEFAULT NULL,
  `RFCBANCOORD` varchar(15) DEFAULT NULL,
